"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7626"],{37457(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.nenhuma_etapa_compoe_nota","status":422,"titulo":"Ao menos uma etapa deve compor a nota final"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.nenhuma_etapa_compoe_nota","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["O corpo do pedido de defini\xe7\xe3o de etapas tem ao menos uma etapa, mas nenhuma delas\\n**comp\xf5e a nota** \u2014 nenhuma \xe9 de car\xe1ter classificat\xf3ria (ou ambas) **com**\\npeso informado (os dois juntos, n\xe3o um ou outro; ver\\n[`etapa_processo.peso_invalido`](/erros/uniplus.selecao.etapa_processo.peso_invalido)).","A confer\xeancia existe para blindar a f\xf3rmula da nota final\\n(`NOTA FINAL = Soma(Etapa \xd7 peso) / divisor`): sem ao menos uma etapa que\\ncomponha a nota, o divisor da f\xf3rmula fica zero \u2014 uma divis\xe3o por zero que a\\nguarda existe para nunca deixar acontecer.","**Uma lista de etapas totalmente vazia n\xe3o dispara este erro** \u2014 \xe9 um estado\\nv\xe1lido, para processos sem prova pr\xf3pria (ex.: SiSU, classifica\xe7\xe3o\\nimportada). A guarda s\xf3 vale quando h\xe1 etapas: com pelo menos uma etapa no\\ncorpo do pedido, ao menos uma precisa compor a nota.","Este c\xf3digo dispara ao **definir etapas**\\n(`PUT .../etapas`)."],"comoResolver":["Garanta que ao menos uma etapa do corpo do pedido tenha `carater` classificat\xf3ria (ou\\nambas) **e** `peso` informado. Se todas as etapas do processo s\xe3o\\neliminat\xf3rias puras (sem compor nota), remova a lista inteira em vez de\\nenviar um conjunto que n\xe3o sustenta a f\xf3rmula da nota final."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);